INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'கணினி வலையமைப்பின் முக்கிய நோக்கம் என்ன?','சாதனங்களுக்கு இடையே தரவு பகிர்வு','CPU உற்பத்தி','கோப்புகளை அழித்தல்','மின்சாரம் சேமித்தல்','சாதனங்களுக்கு இடையே தரவு பகிர்வு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
