INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'TCP/IP தொடர்பாக, tCP எந்த வகை நெறிமுறை? (உதாரணம் 23)','இணைப்பு சார்ந்த','இணைப்பு இல்லாத','கோப்பு முறைமை','வன்பொருள்','இணைப்பு சார்ந்த','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'உடல் அடுக்கு தொடர்பாக, uDP-யின் முக்கிய பண்பு என்ன? (உதாரணம் 24)','வேகமான இணைப்பு இல்லாத பரிமாற்றம்','கட்டாய மறுபரிமாற்றம்','கோப்பு நிர்வாகம்','நினைவக மேலாண்மை','வேகமான இணைப்பு இல்லாத பரிமாற்றம்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'தரவு இணைப்பு அடுக்கு தொடர்பாக, iP முகவரி எதற்காக பயன்படுகிறது? (உதாரணம் 25)','வலையமைப்பில் சாதனத்தை அடையாளப்படுத்த','கோப்பை சுருக்க','CPU திட்டமிட','திரை கட்டுப்படுத்த','வலையமைப்பில் சாதனத்தை அடையாளப்படுத்த','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'MAC முகவரி தொடர்பாக, iPv4 முகவரியின் நீளம் எவ்வளவு? (உதாரணம் 26)','32 பிட்கள்','64 பிட்கள்','16 பிட்கள்','128 பிட்கள்','32 பிட்கள்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'Ethernet தொடர்பாக, iPv6 முகவரியின் நீளம் எவ்வளவு? (உதாரணம் 27)','128 பிட்கள்','32 பிட்கள்','64 பிட்கள்','16 பிட்கள்','128 பிட்கள்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'IP முகவரி தொடர்பாக, dNS-ன் பணி என்ன? (உதாரணம் 28)','டொமைன் பெயரை IP முகவரியாக மாற்றுதல்','கோப்பை அழித்தல்','CPU வேகம் அளத்தல்','மின்சாரம் வழங்குதல்','டொமைன் பெயரை IP முகவரியாக மாற்றுதல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'IPv4 தொடர்பாக, dHCP எதற்காக பயன்படுகிறது? (உதாரணம் 29)','IP அமைப்புகளை தானாக வழங்க','வலைப்பக்கங்களை வடிவமைக்க','கோப்புகளை சுருக்க','CPU இயக்க','IP அமைப்புகளை தானாக வழங்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'IPv6 தொடர்பாக, hTTP எந்த பயன்பாட்டுடன் தொடர்புடையது? (உதாரணம் 30)','வலை பரிமாற்றம்','வட்டு திட்டமிடல்','நினைவக மேலாண்மை','அச்சுப்பொறி இயக்கம்','வலை பரிமாற்றம்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'சப்நெட்டிங் தொடர்பாக, கணினி வலையமைப்பின் முக்கிய நோக்கம் என்ன? (உதாரணம் 31)','சாதனங்களுக்கு இடையே தரவு பகிர்வு','CPU உற்பத்தி','கோப்புகளை அழித்தல்','மின்சாரம் சேமித்தல்','சாதனங்களுக்கு இடையே தரவு பகிர்வு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'ARP தொடர்பாக, oSI மாதிரியில் எத்தனை அடுக்குகள் உள்ளன? (உதாரணம் 32)','7','4','5','9','7','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'ICMP தொடர்பாக, tCP எந்த வகை நெறிமுறை? (உதாரணம் 33)','இணைப்பு சார்ந்த','இணைப்பு இல்லாத','கோப்பு முறைமை','வன்பொருள்','இணைப்பு சார்ந்த','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
