INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Single Choice','Medium',1,'வலையமைப்பு பாதுகாப்பு தொடர்பாக, hTTP எந்த பயன்பாட்டுடன் தொடர்புடையது? (உதாரணம் 40)','வலை பரிமாற்றம்','வட்டு திட்டமிடல்','நினைவக மேலாண்மை','அச்சுப்பொறி இயக்கம்','வலை பரிமாற்றம்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'OSI மாதிரியின் அடுக்குகளில் எவை அடங்கும்?','பயன்பாட்டு அடுக்கு','போக்குவரத்து அடுக்கு','வலையமைப்பு அடுக்கு','தரவு இணைப்பு அடுக்கு','பயன்பாட்டு அடுக்கு; போக்குவரத்து அடுக்கு; வலையமைப்பு அடுக்கு; தரவு இணைப்பு அடுக்கு','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'வலையமைப்பு முகவரிகளின் வகைகள் எவை?','MAC முகவரி','IPv4 முகவரி','IPv6 முகவரி','போர்ட் எண்','MAC முகவரி; IPv4 முகவரி; IPv6 முகவரி; போர்ட் எண்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'TCP-ன் பண்புகள் எவை?','இணைப்பு நிறுவல்','நம்பகமான பரிமாற்றம்','வரிசை கட்டுப்பாடு','மறுபரிமாற்றம்','இணைப்பு நிறுவல்; நம்பகமான பரிமாற்றம்; வரிசை கட்டுப்பாடு; மறுபரிமாற்றம்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'பயன்பாட்டு அடுக்கு நெறிமுறைகள் எவை?','HTTP','DNS','DHCP','SMTP','HTTP; DNS; DHCP; SMTP','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'வலையமைப்பு பாதுகாப்பு முறைகள் எவை?','ஃபயர்வால்','குறியாக்கம்','அங்கீகாரம்','ஊடுருவல் கண்டறிதல்','ஃபயர்வால்; குறியாக்கம்; அங்கீகாரம்; ஊடுருவல் கண்டறிதல்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'OSI மாதிரியின் அடுக்குகளில் எவை அடங்கும்? — பயன்பாட்டு நிலை 6','பயன்பாட்டு அடுக்கு','போக்குவரத்து அடுக்கு','வலையமைப்பு அடுக்கு','தரவு இணைப்பு அடுக்கு','பயன்பாட்டு அடுக்கு; போக்குவரத்து அடுக்கு; வலையமைப்பு அடுக்கு; தரவு இணைப்பு அடுக்கு','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'வலையமைப்பு முகவரிகளின் வகைகள் எவை? — பயன்பாட்டு நிலை 7','MAC முகவரி','IPv4 முகவரி','IPv6 முகவரி','போர்ட் எண்','MAC முகவரி; IPv4 முகவரி; IPv6 முகவரி; போர்ட் எண்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'TCP-ன் பண்புகள் எவை? — பயன்பாட்டு நிலை 8','இணைப்பு நிறுவல்','நம்பகமான பரிமாற்றம்','வரிசை கட்டுப்பாடு','மறுபரிமாற்றம்','இணைப்பு நிறுவல்; நம்பகமான பரிமாற்றம்; வரிசை கட்டுப்பாடு; மறுபரிமாற்றம்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
