INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'OSI மாதிரியின் அடுக்குகளில் எவை அடங்கும்? — பயன்பாட்டு நிலை 26','பயன்பாட்டு அடுக்கு','போக்குவரத்து அடுக்கு','வலையமைப்பு அடுக்கு','தரவு இணைப்பு அடுக்கு','பயன்பாட்டு அடுக்கு; போக்குவரத்து அடுக்கு; வலையமைப்பு அடுக்கு; தரவு இணைப்பு அடுக்கு','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'வலையமைப்பு முகவரிகளின் வகைகள் எவை? — பயன்பாட்டு நிலை 27','MAC முகவரி','IPv4 முகவரி','IPv6 முகவரி','போர்ட் எண்','MAC முகவரி; IPv4 முகவரி; IPv6 முகவரி; போர்ட் எண்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Multiple Choice','Hard',2,'TCP-ன் பண்புகள் எவை? — பயன்பாட்டு நிலை 28','இணைப்பு நிறுவல்','நம்பகமான பரிமாற்றம்','வரிசை கட்டுப்பாடு','மறுபரிமாற்றம்','இணைப்பு நிறுவல்; நம்பகமான பரிமாற்றம்; வரிசை கட்டுப்பாடு; மறுபரிமாற்றம்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
