INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Short Answer','Medium',2,'கணினி வலையமைப்பு என்றால் என்ன?','','','','','தரவு மற்றும் வளங்களை பகிர்ந்து கொள்ள இணைக்கப்பட்ட கணினி மற்றும் சாதனங்களின் அமைப்பு.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Short Answer','Medium',2,'OSI மாதிரி என்றால் என்ன?','','','','','வலையமைப்பு தொடர்பை ஏழு அடுக்குகளாக விளக்கும் கருத்தியல் மாதிரி.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Short Answer','Medium',2,'IP முகவரி என்றால் என்ன?','','','','','வலையமைப்பில் ஒரு சாதனத்தின் தருக்க அடையாளமாக பயன்படும் முகவரி.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Short Answer','Medium',2,'TCP என்றால் என்ன?','','','','','நம்பகமான, வரிசைப்படுத்தப்பட்ட மற்றும் இணைப்பு சார்ந்த தரவு பரிமாற்றத்தை வழங்கும் போக்குவரத்து நெறிமுறை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Short Answer','Medium',2,'DNS என்றால் என்ன?','','','','','மனிதர்கள் படிக்கக்கூடிய டொமைன் பெயர்களை IP முகவரிகளுடன் தொடர்புபடுத்தும் சேவை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Short Answer','Medium',2,'கணினி வலையமைப்பு என்றால் என்ன? (விரிவாக்கக் கேள்வி 6)','','','','','தரவு மற்றும் வளங்களை பகிர்ந்து கொள்ள இணைக்கப்பட்ட கணினி மற்றும் சாதனங்களின் அமைப்பு.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Short Answer','Medium',2,'OSI மாதிரி என்றால் என்ன? (விரிவாக்கக் கேள்வி 7)','','','','','வலையமைப்பு தொடர்பை ஏழு அடுக்குகளாக விளக்கும் கருத்தியல் மாதிரி.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
