INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Long Answer','Hard',5,'வலையமைப்பு பாதுகாப்பு முறைகளை விளக்குக. (பயன்பாட்டு நிலை 15)','','','','','ஃபயர்வால், குறியாக்கம், அங்கீகாரம், அணுகல் கட்டுப்பாடு, ஊடுருவல் கண்டறிதல் மற்றும் பாதுகாப்பான நெறிமுறைகள் போன்றவை வலையமைப்பை பாதுகாக்க உதவுகின்றன.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Long Answer','Hard',5,'OSI மாதிரியின் ஏழு அடுக்குகளை விளக்குக. (பயன்பாட்டு நிலை 16)','','','','','உடல், தரவு இணைப்பு, வலையமைப்பு, போக்குவரத்து, அமர்வு, வழங்கல் மற்றும் பயன்பாட்டு அடுக்குகள் முறையே தரவு பரிமாற்றத்தின் வெவ்வேறு பணிகளை கையாளுகின்றன.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Long Answer','Hard',5,'TCP மற்றும் UDP-ஐ ஒப்பிடுக. (பயன்பாட்டு நிலை 17)','','','','','TCP இணைப்பு சார்ந்தது, நம்பகமான பரிமாற்றம், வரிசை கட்டுப்பாடு மற்றும் மறுபரிமாற்றம் வழங்குகிறது. UDP இணைப்பு இல்லாதது மற்றும் குறைந்த மேலாண்மைச் செலவுடன் வேகமாக செயல்படுகிறது.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Long Answer','Hard',5,'IPv4 மற்றும் IPv6-ஐ விளக்குக. (பயன்பாட்டு நிலை 18)','','','','','IPv4 32 பிட் முகவரியையும் IPv6 128 பிட் முகவரியையும் பயன்படுத்துகின்றன. IPv6 மிகப் பெரிய முகவரி இடத்தையும் பல மேம்பட்ட வசதிகளையும் வழங்குகிறது.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_computer_networks_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Computer Network','தமிழ்','Long Answer','Hard',5,'DNS செயல்பாட்டை விளக்குக. (பயன்பாட்டு நிலை 19)','','','','','பயனர் டொமைன் பெயரை கோரும்போது DNS அமைப்பு பொருத்தமான IP முகவரியை கண்டறிந்து வழங்குகிறது. இதனால் பயனர்கள் எண் முகவரிகளை நினைவில் வைத்திருக்க வேண்டியதில்லை.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
